# Source for q/ae-anatphys4.js: Anatomy (septa, veins, valves, embryology) + Physiology (cycle, sounds, PV loops, special states) fourth batch.
AN="Anatomy"; PH="Physiology"
Q=[
# --- Septa and valves ---
(AN,"The four parts of the ventricular septum are:","Membranous, inlet, trabecular (muscular) and outlet",["Primum, secundum, venosus and coronary","Anterior, posterior, lateral and apical","Basal, mid, apical and cap"],"VSDs are named by the part of the septum they involve.","F"),
(AN,"The flap of the foramen ovale is formed by the:","Septum primum",["Septum secundum","Crista terminalis","Moderator band"],"The septum secundum forms the thicker rim (limbus).","F"),
(AN,"The limbus of the fossa ovalis is formed by the:","Septum secundum",["Septum primum","Eustachian valve","Coronary sinus"],"Lipomatous hypertrophy spares the thin fossa itself.","C"),
(AN,"The three cusps of the pulmonic valve are usually named:","Anterior, right and left",["Right coronary, left coronary and noncoronary","Septal, anterior and posterior","Anterior and posterior only"],"The aortic cusps are named for the coronary arteries.","C"),
(AN,"The four pulmonary veins are the:","Right upper, right lower, left upper and left lower",["Superior, inferior, medial and lateral","Anterior, posterior, right and left only","Two right and one left"],"Variations, such as a common left trunk, are common.","F"),
(AN,"The aortic 'annulus' measured on echo is really:","A virtual ring joining the lowest points (nadirs) of the three cusp attachments",["A thick fibrous ring","The sinotubular junction","The LVOT 2 cm below the valve"],"It is the plane used for TAVR sizing.","C"),
(AN,"The interleaflet triangles of the aortic root lie:","Between the cusp attachments, below the commissures",["Inside the coronary arteries","In the mitral valve","In the pericardium"],"They are thin areas of the LVOT wall.","C"),
# --- Veins ---
(AN,"The middle cardiac vein runs in the:","Posterior interventricular groove, alongside the PDA",["Anterior interventricular groove","Left AV groove","Atrial septum"],"It drains into the coronary sinus.","C"),
(AN,"The anterior cardiac veins drain mainly the RV and empty:","Directly into the right atrium",["Into the coronary sinus","Into the LA","Into the pulmonary veins"],"Most other cardiac veins drain via the coronary sinus.","C"),
(AN,"The small cardiac vein runs with the:","Right coronary artery in the right AV groove",["LAD","LCx","Pulmonary artery"],"It drains into the coronary sinus.","C"),
(AN,"The pericardium receives most of its nerve supply for pain through the:","Phrenic nerves",["Vagus nerve only","Spinal accessory nerve","Femoral nerve"],"This is why pericarditis pain can be felt in the shoulder.","C"),
(AN,"The cardiac plexus contains nerves from:","Both the sympathetic chain and the vagus nerve",["Only the phrenic nerve","Only spinal nerves","The femoral nerve"],"It controls heart rate and contractility.","F"),
# --- Embryology ---
(AN,"The embryonic heart starts beating at about:","3 weeks (around day 22)",["12 weeks","24 weeks","Birth"],"It is the first organ to function.","F"),
(AN,"During early development, the straight heart tube normally loops to the:","Right (dextro-looping)",["Left","It does not loop","Downward only"],"Abnormal looping leads to problems such as congenitally corrected transposition.","C"),
(AN,"The endocardial cushions form the:","AV septum and parts of the mitral and tricuspid valves",["Aortic arch","Pulmonary veins","Coronary sinus"],"Defects cause AV canal anomalies.","F"),
(AN,"The truncus arteriosus divides into the aorta and pulmonary artery by forming a:","Spiral septum",["Straight septum","Horizontal septum","No septum"],"Failure of division gives persistent truncus; failure to spiral can cause TGA.","F"),
(AN,"Neural crest cells are important for development of the:","Outflow tract (conotruncal septum)",["Coronary sinus only","Mitral valve only","LV apex"],"Neural crest problems link to DiGeorge-type defects.","C"),
(AN,"The smooth part of the right atrium (sinus venarum) develops from the:","Sinus venosus",["Bulbus cordis","Primitive ventricle","Truncus arteriosus"],"The trabeculated part and appendage come from the primitive atrium.","C"),
(AN,"The bulbus cordis forms mainly the:","RV outflow tract and the outflow parts of both ventricles",["LA","Pulmonary veins","Coronary sinus"],"The primitive ventricle forms most of the LV.","C"),
(AN,"The left fourth pharyngeal arch artery forms part of the:","Aortic arch",["Pulmonary arteries","Carotid arteries","Coronary arteries"],"The sixth arch forms the pulmonary arteries and ductus arteriosus.","C"),
(AN,"The ductus arteriosus develops from the:","Sixth pharyngeal arch artery (left side)",["Third arch","Fourth arch only","First arch"],"The third arch forms the carotid arteries.","C"),
(AN,"The pulmonary veins join the left atrium by:","A common pulmonary vein that becomes part of the LA wall",["Draining into the RA first","Joining the aorta","Joining the coronary sinus"],"Failure of this step causes anomalous pulmonary venous return.","C"),
# --- Physiology: cardiac cycle ---
(PH,"The phases of the cardiac cycle in order (starting with atrial contraction) are:","Atrial systole, isovolumic contraction, ejection, isovolumic relaxation, then filling",["Filling, ejection, atrial systole, relaxation","Ejection, atrial systole, filling, contraction","Relaxation, ejection, filling, contraction"],"Ejection has rapid and reduced phases; filling has rapid filling and diastasis.","F"),
(PH,"The first heart sound occurs at about the same time as:","The end of the QRS complex (mitral and tricuspid closure)",["The P wave","The end of the T wave","The PR segment only"],"S2 occurs near the end of the T wave.","F"),
(PH,"Fixed splitting of S2 that does not change with breathing is typical of:","Atrial septal defect",["LBBB","Aortic stenosis","Normal heart"],"Both ventricles fill from the shared atrial pool.","F"),
(PH,"Paradoxical (reversed) splitting of S2 happens when:","Aortic closure is delayed, such as in LBBB or severe AS",["Pulmonic closure is delayed","There is an ASD","Breathing stops"],"The split narrows with inspiration instead of widening.","C"),
(PH,"Wide splitting of S2 that still moves with breathing is seen with:","Right bundle branch block or pulmonic stenosis",["LBBB","Aortic stenosis","Hypertrophic cardiomyopathy"],"Delayed RV emptying delays pulmonic closure.","C"),
(PH,"A loud S1 with an opening snap after S2 is classic for:","Mitral stenosis",["Aortic regurgitation","Mitral prolapse","Tamponade"],"The stiff leaflets snap open at the start of diastole.","F"),
(PH,"A shorter interval between S2 and the opening snap in mitral stenosis suggests:","More severe stenosis (higher LA pressure)",["Milder stenosis","Normal valve","Aortic stenosis"],"High LA pressure opens the valve sooner.","C"),
(PH,"The reduced ejection phase occurs when:","Ventricular pressure begins to fall but blood still flows into the aorta by momentum",["The aortic valve is closed","The mitral valve is open","The atria contract"],"It ends with aortic valve closure.","C"),
# --- Pressure-volume loops ---
(PH,"On a pressure-volume loop, increasing preload (with no other change) makes:","The loop wider, with a larger stroke volume",["The loop narrower","No change","The ESPVR flatter"],"More filling means more stretch and stronger ejection.","F"),
(PH,"On a pressure-volume loop, increasing afterload (with no other change) makes:","Stroke volume smaller and end-systolic volume larger",["Stroke volume larger","No change","EF higher"],"The ventricle cannot empty as much against higher pressure.","F"),
(PH,"Reduced LV compliance (stiffness) shifts the end-diastolic pressure-volume relationship:","Upward and to the left, so pressure rises more for the same volume",["Downward","To the right only","Not at all"],"This is seen in HFpEF and hypertrophy.","C"),
(PH,"The area inside the pressure-volume loop represents:","Stroke work",["Ejection fraction","Heart rate","Cardiac output"],"Stroke work is pressure times volume.","F"),
(PH,"Elastance of the ventricle describes:","How much pressure changes for a change in volume (stiffness)",["Heart rate","Blood viscosity","Valve area"],"End-systolic elastance reflects contractility.","C"),
(PH,"Ventricular–arterial coupling refers to:","How well the ventricle's contractility matches the arterial load",["How valves open","How the ECG is recorded","How coronary arteries fill"],"Poor coupling reduces efficiency.","C"),
# --- Hypertrophy and adaptation ---
(PH,"Pressure overload (such as AS or hypertension) usually causes:","Concentric hypertrophy, with sarcomeres added in parallel",["Eccentric hypertrophy with dilation","No change","Thinning of walls"],"Walls thicken to normalize wall stress.","F"),
(PH,"Volume overload (such as AR or MR) usually causes:","Eccentric hypertrophy, with sarcomeres added in series and chamber dilation",["Concentric hypertrophy","Small chambers","No change"],"The chamber enlarges to handle extra volume.","F"),
(PH,"The heart's main fuel at rest is:","Fatty acids",["Glucose only","Protein","Alcohol"],"It can switch to glucose and lactate when needed.","C"),
(PH,"In the RV, coronary blood flow occurs:","In both systole and diastole, because RV pressure is low",["Only in diastole","Only in systole","Never"],"LV flow occurs mainly in diastole.","C"),
(PH,"Coronary steal can occur when:","A vasodilator increases flow to normal areas and takes blood away from areas beyond a narrowing",["Coronaries narrow everywhere","Heart rate falls","A valve leaks"],"This is the basis of vasodilator stress testing.","C"),
(PH,"Coronary collateral vessels develop to:","Supply myocardium beyond a slowly narrowing artery",["Drain the coronary sinus","Carry lymph","Connect veins to the aorta"],"Good collaterals can limit the size of an MI.","F"),
# --- Fick, edema and reflexes ---
(PH,"The Fick principle calculates cardiac output as:","Oxygen consumption ÷ (arterial − venous oxygen content)",["Stroke volume × BSA","Heart rate ÷ oxygen","Blood pressure × heart rate"],"It is a reference method for measuring cardiac output.","C"),
(PH,"Thermodilution measures cardiac output by:","Injecting cold fluid into the RA and measuring temperature change in the PA",["Measuring LVOT VTI","Counting heart rate","Measuring BSA"],"It is done with a pulmonary artery catheter.","C"),
(PH,"Pulmonary edema usually develops when LA (wedge) pressure rises above about:","18 to 25 mmHg",["5 mmHg","10 mmHg","2 mmHg"],"Fluid leaks from capillaries faster than lymph can remove it.","C"),
(PH,"Fluid moves out of capillaries when:","Capillary hydrostatic pressure exceeds plasma oncotic pressure",["Oncotic pressure is higher","Pressures are equal","Lymph flow increases"],"Low albumin lowers oncotic pressure and promotes edema.","F"),
(PH,"The Bainbridge reflex causes:","Heart rate to increase when the atria are stretched by increased venous return",["Heart rate to fall with stretch","Blood pressure to fall","No change in heart rate"],"It helps match heart rate to venous return.","C"),
(PH,"Respiratory sinus arrhythmia is:","A normal rise in heart rate with inspiration and fall with expiration",["A dangerous arrhythmia","Atrial fibrillation","Heart block"],"It is most obvious in young, healthy people.","F"),
(PH,"Vascular compliance means:","How much a vessel's volume changes with a change in pressure",["Vessel resistance","Blood viscosity","Heart rate"],"Stiff arteries in older people raise systolic pressure and pulse pressure.","F"),
# --- Pregnancy and other states ---
(PH,"In normal pregnancy, cardiac output increases by about:","30% to 50%",["5%","100% to 200%","It falls"],"Increases peak in the second trimester.","F"),
(PH,"In normal pregnancy, systemic vascular resistance:","Falls",["Rises sharply","Stays exactly the same","Doubles"],"Blood pressure often falls slightly in mid-pregnancy.","F"),
(PH,"Lying flat on the back late in pregnancy can lower blood pressure because:","The uterus compresses the IVC and reduces venous return",["Heart rate stops","The aorta dilates","The LV hypertrophies"],"Tilt the patient to the left during the exam.","F"),
(PH,"In normal pregnancy, plasma volume:","Rises by about 40% to 50%",["Falls","Stays the same","Rises by 5%"],"This causes a mild dilutional anemia.","C"),
(PH,"At high altitude, the main heart and lung response is:","Faster heart rate and pulmonary artery constriction",["Lower heart rate","Lower PA pressure","No change"],"Long-term exposure can cause pulmonary hypertension.","F"),
(PH,"In anemia, cardiac output rises mainly because:","Blood viscosity falls and tissues need more blood flow to get oxygen",["Viscosity rises","Heart rate falls","Afterload rises"],"Severe anemia can cause high-output heart failure.","F"),
(PH,"In sepsis, early hemodynamics often show:","Low systemic vascular resistance with high cardiac output",["High SVR and low output always","Normal values","Pericardial effusion"],"Later, septic cardiomyopathy may reduce LV function.","C"),
(PH,"An arteriovenous fistula for dialysis can cause:","High cardiac output and LV dilation",["Low cardiac output","Mitral stenosis","Aortic stenosis"],"Large fistulas increase the heart's workload.","C"),
(PH,"The total blood volume of an average adult is about:","5 liters",["1 liter","10 liters","500 mL"],"About 70 mL per kg of body weight.","F"),
(PH,"Most of the blood volume at rest is in the:","Veins",["Arteries","Capillaries","Heart chambers"],"Veins act as a reservoir (capacitance vessels).","F"),
(PH,"An S3 heart sound occurs during early diastole and is linked to:","Rapid early filling into a stiff or overloaded ventricle",["Atrial contraction","Valve opening","Aortic valve closure"],"S3 can be normal in children and young adults.","F"),
(PH,"An S4 is absent in atrial fibrillation because:","There is no effective atrial contraction",["The ventricle is too stiff","The mitral valve is closed","S4 occurs in systole"],"S4 needs atrial contraction into a stiff ventricle.","F"),
]
